 "content": "def transform(grid):
    """Move all non-background cells down by one row, clipping at the bottom."""
    if not grid:
        return []
    background = grid[0][0]
    h, w = len(grid), len(grid[0])
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
